	//   t is a valid departure time (t = 300 + k*b, k >= 0, t <= 1439)
	//   simionDeparture - tb < t < simionArrival

	// Let's find the range of t:
	// t > simionDeparture - tb  =>  t >= simionDeparture - tb + 1 (since t is integer)
	// t < simionArrival         =>  t <= simionArrival - 1

	// Also t must be in [300, 1439] and t = 300 + k*b for some integer k >= 0

	minT := simionDeparture - tb + 1
	maxT := simionArrival - 1

	// Clamp to valid range
