		minT = 300
	}
	if maxT > 1439 {
		maxT = 1439
	}

	if minT > maxT {
		fmt.Println(0)
		return
	}

	// Count t in [minT, maxT] such that t = 300 + k*b for some integer k >= 0
	// t - 300 must be divisible by b and t - 300 >= 0

	// Find the smallest k such that 300 + k*b >= minT
	// k >= (minT - 300) / b
