		// k must satisfy 300 + k*b >= minT => k >= (minT - 300 + b - 1) / b (ceiling)
		rem := (minT - 300) % b
		if rem == 0 {
			minK := (minT - 300) / b
		} else {
			minK := (minT - 300) / b + 1
		}
